GROUP = sys.argv[1] if len(sys.argv) > 1 else None
CASES = []
def case(name, f): CASES.append((name, f))
def outcome(f):
    try:
        r = f()
        try: n = len(r)
        except BaseException: n = ""
        return "ok %s %s" % (type(r).__name__, n)
    except BaseException as e:
        return type(e).__name__
